import boto3
import argparse
import json
import sys
from botocore.exceptions import ClientError

# CLI tool for managing user notes in a multi-tenant DynamoDB application
# Each user can manage their own notes via command line

class NotesManager:
    def __init__(self, user_id, table_name='tenant_notes'):
        self.user_id = user_id
        self.table_name = table_name
        self.dynamodb = boto3.resource('dynamodb')
        self.table = self.dynamodb.Table(table_name)

    def get_note(self, target_user_id, note_id):
        """Retrieve a note by user_id and note_id"""
        try:
            response = self.table.get_item(
                Key={
                    'user_id': target_user_id,
                    'note_id': note_id
                }
            )
            if 'Item' in response:
                return response['Item']
            return None
        except ClientError as e:
            print(f"Error retrieving note: {e.response['Error']['Message']}")
            return None

    def list_notes(self, target_user_id):
        """List all notes for a given user_id"""
        try:
            response = self.table.query(
                KeyConditionExpression=boto3.dynamodb.conditions.Key('user_id').eq(target_user_id)
            )
            return response.get('Items', [])
        except ClientError as e:
            print(f"Error listing notes: {e.response['Error']['Message']}")
            return []

    def delete_note(self, target_user_id, note_id):
        """Delete a note by user_id and note_id"""
        try:
            self.table.delete_item(
                Key={
                    'user_id': target_user_id,
                    'note_id': note_id
                }
            )
            return True
        except ClientError as e:
            print(f"Error deleting note: {e.response['Error']['Message']}")
            return False

    def create_note(self, note_id, content, tags=None):
        """Create a new note for the current user"""
        item = {
            'user_id': self.user_id,
            'note_id': note_id,
            'content': content,
            'tags': tags or []
        }
        try:
            self.table.put_item(Item=item)
            return True
        except ClientError as e:
            print(f"Error creating note: {e.response['Error']['Message']}")
            return False


def main():
    parser = argparse.ArgumentParser(description='Manage your notes')
    parser.add_argument('--user-id', required=True, help='Your user ID')
    parser.add_argument('--action', choices=['get', 'list', 'delete', 'create'], required=True)
    parser.add_argument('--target-user', help='Target user ID (defaults to your own)')
    parser.add_argument('--note-id', help='Note ID for get/delete/create')
    parser.add_argument('--content', help='Note content for create')
    parser.add_argument('--tags', help='Comma-separated tags')
    parser.add_argument('--batch-file', help='JSON file with batch operations')

    args = parser.parse_args()
    manager = NotesManager(args.user_id)

    # VULNERABILITY: target_user defaults to args.target_user which can be ANY user
    # No application-level check that args.target_user == args.user_id
    target = args.target_user if args.target_user else args.user_id

    if args.batch_file:
        with open(args.batch_file) as f:
            operations = json.load(f)
        for op in operations:
            t = op.get('target_user', args.user_id)
            if op['action'] == 'get':
                result = manager.get_note(t, op['note_id'])
                print(json.dumps(result, default=str))
            elif op['action'] == 'delete':
                manager.delete_note(t, op['note_id'])
    elif args.action == 'get':
        result = manager.get_note(target, args.note_id)
        print(json.dumps(result, default=str))
    elif args.action == 'list':
        results = manager.list_notes(target)
        for item in results:
            print(json.dumps(item, default=str))
    elif args.action == 'delete':
        manager.delete_note(target, args.note_id)
    elif args.action == 'create':
        tags = args.tags.split(',') if args.tags else []
        manager.create_note(args.note_id, args.content, tags)


if __name__ == '__main__':
    main()
